        /// Realiza la aprobación de la solicitud de servicio y el equipo de computo.
        /// </summary>
        /// <param name="sender"></param>
        /// <param name="e"></param>
        private void BtnAprobacionComputo_Execute(object sender, SimpleActionExecuteEventArgs e)
        {
            var space = Application.CreateObjectSpace(typeof(SolicitudServicioEquipoComputo));
            var eq = RecordHelper.GetCurrentObject<SolicitudServicioEquipoComputo>(space, View, e.CurrentObject);

            if (eq.Master is null)
                Message.ShowAlert("Entidad Solicitud Servicio Invalida. Contacte a sistemas.",InformationType.Info);

            if (eq.IsAprobacionComputoValida.Item1)
                eq.AprobarEqComputo();

            if (space.IsModified)
                space.CommitChanges();

            ObjectSpace.Refresh();
        }

