/// <summary>
        /// Aprueba la solicitud de servicio.
        /// </summary>
        /// <param name="sender"></param>
        /// <param name="e"></param>
        private void AprobarSolicitudServicio(object sender, SimpleActionExecuteEventArgs e)
        {
            var solicitudEmpleado = ObtenerDatoSolicitud(e);

            try
            {
                var aprobacion = solicitudEmpleado.Item1.AprobarSolicitudServicio();
                if (!aprobacion.Item1)
                {
                    Message.ShowAlertDialog("Aprobación de Solicitud", aprobacion.Item2, InformationType.Info);
                    return;
                }

                if (ObjectSpace.IsModified)
                    ObjectSpace.CommitChanges();

                EnviarEmail(solicitudEmpleado.Item1.Session, solicitudEmpleado.Item1);
            }
            catch (Exception ex)
            {
                ObjectSpace.Rollback();
                throw new UserFriendlyException($"{ex.Message}");
            }

            finally
            {
                ObjectSpace.Refresh();
            }
        }

