public decimal CalcularCalificacionAuditoria()
{
    decimal totalAuditoria = 0m;
    if (this == null)
        return totalAuditoria;

    // Lógica para calcular la calificación de la auditoría
    foreach (var grupo in ChecklistVersion.ChecklistCriterioGrupos)
    {
        var calificacion = CalcularCalificacionGrupo(grupo);

        var contibucionGrupo = (calificacion / 100) * grupo.Ponderacion;
        totalAuditoria += contibucionGrupo;
    }
    return totalAuditoria;
}

