/// <summary>
    /// Valida que la fecha de aniversario de una programación de pago coincida con el día esperado
    /// ajustado según el aniversario del contrato.
    /// </summary>
    /// <param name="fechaAniversarioProgramacion">La fecha de aniversario de la programación</param>
    /// <param name="fechaAniversarioContrato">La fecha de aniversario del contrato</param>
    /// <param name="folioProgramacion">El folio de la programación (para mensajes de error)</param>
    /// <param name="folioContrato">El folio del contrato (para mensajes de error)</param>
    /// <returns>
    /// Una tupla con:
    /// - esValido: true si la validación es correcta, false en caso contrario
    /// - mensajeError: el mensaje de error descriptivo si la validación falla, null si es válida
    /// </returns>
    public static (bool esValido, string mensajeError) ValidarFechaAniversarioAjustada(
        DateTime fechaAniversarioProgramacion, 
        DateTime fechaAniversarioContrato,
        string folioProgramacion = null,
        string folioContrato = null)
    {
        // Validar que las fechas no sean DateTime.MinValue
        if (fechaAniversarioProgramacion == DateTime.MinValue)
            return (false, $"La programación {folioProgramacion ?? "sin folio"} no tiene fecha de aniversario definida.");

        if (fechaAniversarioContrato == DateTime.MinValue)
            return (false, $"El contrato {folioContrato ?? "sin folio"} no tiene fecha de aniversario definida.");

