    {
        get
        {
            // Solo valida si se está guardando una ProgramacionPago, no cuando se guarda el Contrato
            if (Session.IsObjectToSave(this) == false)
                return true;

            if (Contrato != null && FechaAniversario != DateTime.MinValue && (Estatus != TipoEstatus.Finalizado || Estatus != TipoEstatus.Cancelado))
            {
                if ((FechaAniversario.Date < Contrato.FechaInicio.Date) || FechaAniversario.Date > Contrato.FechaVencimiento.Date)
                {
                    MensajeErrorCompartido = "La fecha de aniversario no puede ser anterior a la fecha de inicio del contrato, ni posterior a la fecha de vencimiento.";
                    return false;
                }

                if(!IsAdquisicion && !IsRenovacion)
                {
                    // Usar el método unificado de validación
                    var (esValido, mensajeError) = ProgramacionPagoHelper.ValidarFechaAniversarioAjustada(
                        FechaAniversario,
                        Contrato.FechaAniversario);

                    if (!esValido)
                    {
                        MensajeErrorCompartido = mensajeError;
                        return false;
                    }
                }
            }

            return true;
        }
    }

