        {
            base.OnEstatusUpdated(oldValue);

            switch (Estatus)
            {
                case TipoEstatus.Cancelado:
                    PersonalCancela = Session.CurrentUser()?.Employee(Session);
                    FechaCancela = DataHelper.ServerDateTime(Session);

                    var salidaComputo = Session.Query<AlmacenComputoSalida>().Where(p => p.Traspaso.Oid == Oid).SingleOrDefault();
                    if (salidaComputo != null)
                        salidaComputo.CancelarSalidaComputo();

                    foreach (var item in TraspasoActivo)
                        item.ActivoComputo.CancelaTraspaso(item);

                    break;
                default: // Any
                    break;
            }
        }

