/// <summary>
        /// CANCELACION DEL TRASPASO
        /// </summary>
        /// <param name="trasDetActivo"></param>
        public void CancelaTraspaso(TraspasoComputoActivo trasDetActivo)
        {
            if (Estatus == TipoEstatus.Cancelado)
                throw new Exception($"Activo no puede ser alterado. Estatus de Activo {TipoEstatus.Cancelado.ToString()}");

            EliminaAsignacionActivoComputo($"ACTIVO RECUPERADO POR CANCELACIÓN DE TRASPASO CON FOLIO {trasDetActivo.Traspaso.Folio}");

            Almacen = trasDetActivo.Traspaso.AlmacenOrigen;
            Ubicacion = trasDetActivo.UbicacionOrigen;

            AuditHelper.Add(Session, this, Estatus.ToDescription().ToUpper(), $"CANCELACIÓN DE TRASPASO CON FOLIO {trasDetActivo.Traspaso.Folio}");

            RegistraTrazabilidad("TRASPASO", "CANCELACIÓN DE TRASPASO", trasDetActivo.Oid, trasDetActivo.Traspaso.Folio, typeof(TraspasoComputoActivo).Namespace);


        }

