private void ValidacionCantidadesLicencias()
    {
        if (!Programaciones.Any())
            return;

        var programacionesActivas = Programaciones.Where(p => p.ProgramacionPago != null && p.Estatus != TipoEstatus.Cancelado).ToList();

        foreach (var item in programacionesActivas)
        {
            var pp = item.ProgramacionPago;

            if (pp.OrdenCompra is null || pp.Contrato is null || pp.Contrato.BovedaLicencias is null || pp.IsAdquisicion)
                continue;

            var errorOrden = BovedaLicenciaHelper.ValidarLicenciaRenovarIgualOrdencompraContratoActual(pp, Session);
            if (!string.IsNullOrEmpty(errorOrden))
                throw new UserFriendlyException(errorOrden);

            var errorBoveda = BovedaLicenciaHelper.ValidaLicenciasProgramacion(pp, Session);
            if (!string.IsNullOrEmpty(errorBoveda))
                throw new UserFriendlyException(errorBoveda);

            var errorRenovacion = BovedaLicenciaHelper.ValidaLicenciasRenovacion(pp, Session);
            if (!string.IsNullOrEmpty(errorRenovacion))
                throw new UserFriendlyException(errorRenovacion);
        }
    }

