/// <summary>
    /// 
    /// </summary>
    /// <param name="programacion"></param>
    /// <param name="Session"></param>
    /// <returns></returns>
    public static string ValidarLicenciaRenovarIgualBovedaLicenciasActivas(ProgramacionPago programacion, Session Session)
    {
        if (programacion.Contrato != null)
        {
            if (programacion.Contrato.BovedaLicencias != null)
            {
                var auxBovedaLic = Session.Query<BovedaLicencia>().FirstOrDefault(x => x.Contrato.Oid == programacion.Contrato.Oid && x.Estatus != Base.TipoEstatus.Cancelado);
                if (auxBovedaLic != null)
                {
                    var cantLicenciasBovedaLic = auxBovedaLic.Detalles.Where(p => p.Estatus != TipoEstatus.Cancelado).Count();
                    if (cantLicenciasBovedaLic != programacion.CantidadLicenciaRenovar)
                        return $"La cantidad a renovar en la programación de pago # {programacion.Folio} deberá ser igual a la Cantidad de licencias en la boveda relacionada al contrato #{programacion.Contrato.Folio}. Favor de homologar el número de licencias con la cantidad a renovar.";
                }
            }
        }

        return string.Empty;
    }

