public static string ValidaLicenciasProgramacion(ProgramacionPago programacion, Session session)
    {
        if (programacion.Contrato is null || programacion.Contrato.BovedaLicencias is null)
            return $"El contrato asociado a la programación de pago #{programacion.Folio} no cuenta con una bóveda de licencias relacionada.";

        var bovedaLicencia = programacion.Contrato.BovedaLicencias;
        if (bovedaLicencia is null)
            return $"La bóveda de licencias relacionada al contrato #{programacion.Contrato.Folio} no existe.";

        var totalLicencias = programacion.CantidadLicenciaRenovar + programacion.CantidadLicenciaAdicional;
        if (totalLicencias != bovedaLicencia.Detalles.Where(p => p.Estatus != TipoEstatus.Cancelado).Count())
            return $"La cantidad total de licencias  ({totalLicencias}) en la programación de pago #{programacion.Folio} no corresponde con la boveda de licencias #{programacion.Contrato.Folio}, licencias en boveda ({bovedaLicencia.Disponible}).";

        return string.Empty;
    }

