public static DateTime CalcularFechaCandidata(DateTime fechaInicio, int periodicidadMeses, DateTime fechaActual)
    {
        // Calcular años y meses completos transcurridos
        var años = fechaActual.Year - fechaInicio.Year;
        var meses = fechaActual.Month - fechaInicio.Month;

        // Ajustar si el día actual es menor que el día de inicio
        if (fechaActual.Day < fechaInicio.Day)
            meses--;

        var totalMeses = años * 12 + meses;
        if (totalMeses < 0)
            totalMeses = 0;

        // Calcular cuantos periodos completos han pasado a partir de la fecha de inicio del contrato con respecto a la fecha actual considerando la periodicidad del contrato (meses)
        //¿ Por que en meses? por que es mas facil de trabajar que con dias y evita errores relacionados con la duración variable de los meses. 
        var periodosCompletos = (int)Math.Floor((double)totalMeses / periodicidadMeses);

        // Sumar los periodos completos * periodicidadMeses a la fecha inicio
        return fechaInicio.AddMonths(periodosCompletos * periodicidadMeses);
    }

