        /// </summary>
        /// <param name="e"></param>
        /// <exception cref="UserFriendlyException"></exception>
        private void GenerarProrrateo(SimpleActionExecuteEventArgs e)
        {
            using var space = Application.CreateObjectSpace(typeof(ProgramacionPago));

            var programacion = RecordHelper.GetCurrentObject<ProgramacionPago>(space, View, e.CurrentObject);

            if (programacion.Contrato is null || !programacion.Contrato.ContratosProrrateoGasto.Any())
                throw new UserFriendlyException("¡La programación seleccionada no tiene un contrato válido para generar el prorrateo!");

            if (programacion.CentroTrabajo is null)
                throw new UserFriendlyException("¡La programación seleccionada no tiene un centro de trabajo válido para generar el prorrateo!");

            var session = space.Session();
            var fechaServidor = DataHelper.ServerDateTime(session);

            // Obtener fecha candidata a partir de la fecha actual
            var fechaCandidata = ProgramacionPagoHelper.CalcularFechaCandidata(
                programacion.Contrato.FechaAniversario.Date,
                programacion.Contrato.PeriodoPago.ValorPeriodoMes,
                fechaServidor.Date);

