/// <summary>
    /// Calcula el día esperado ajustado para una fecha de aniversario, aplicando lógica similar a MAKE_DATE con LEAST.
    /// Si el día base no existe en el mes de la fecha objetivo, se ajusta al último día válido del mes.
    /// </summary>
    /// <param name="diaBaseContrato">El día de aniversario del contrato</param>
    /// <param name="fechaObjetivo">La fecha para la cual se calculará el día ajustado</param>
    /// <returns>El día ajustado (el menor entre el día base y el último día del mes)</returns>
    public static int CalcularDiaAjustadoAniversario(int diaBaseContrato, DateTime fechaObjetivo)
    {
        // Obtener el último día válido del mes de la fecha objetivo
        var ultimoDiaDelMes = DateTime.DaysInMonth(fechaObjetivo.Year, fechaObjetivo.Month);

        // Retornar el menor entre el día base y el último día del mes (lógica LEAST)
        return Math.Min(diaBaseContrato, ultimoDiaDelMes);
    }

