/// <summary>
    /// Obtiene los detalles de licencias de una orden de compra en una renovación.
    /// </summary>
    /// <param name="ordenCompra"></param>
    /// <param name="Session"></param>
    /// <returns></returns>
    public static List<OrdenCompraDetalle> ObtenerDatosLicenciaDeOrdenCompraFromRenovacion(OrdenCompra ordenCompra, Session Session)
    {
        ArgumentNullException.ThrowIfNull(ordenCompra,
        "La orden de compra es requerida en el proceso de agregar licencias adicionales.");

        var listaOrdenCompraDetalle = new List<OrdenCompraDetalle>();

        foreach (var detalle in ordenCompra.Detalles)
        {
            var producto = Session.GetObjectByKey<Producto>(new Guid(detalle.ProductoLigero?.ProductoID));
            for (var index = 0; index < detalle.CantidadSolicitada; index++)
            {
                if (producto.EsLicencia)
                    listaOrdenCompraDetalle.Add(detalle);
            }
        }
        return listaOrdenCompraDetalle;
    }

